// LLM provider metadata and brand icons for the bot homepage.
//
// The icons are inlined as SVG markup (copied from the Open Agent Connect
// platform asset set at src/ui/assets/platforms/) so the bot homepage renders
// correct provider branding on every host without
// each host having to serve its own static asset directory. Inlining mirrors
// how the Browser shell's own chrome icons work (see iconHtml() in app.ts).
//
// `<title>` elements are intentionally stripped: the chips already expose the
// provider name as visible text, and a title would otherwise duplicate the
// accessible name when the same provider appears as both Primary and Fallback.
//
// Note: some icons reference a gradient by id (e.g. codex's
// `lobe-icons-codex-_R_0_`). Each id is unique per provider, so inlining the
// same icon twice (Primary + Fallback) is safe: browsers resolve a duplicate
// id reference to the first matching <defs>, and the gradients are identical.
// Exported as data (not behavior) so buildBrowserPageScript() can inject them
// into the self-contained browser page script via JSON.stringify. The browser
// VM has no module loader, so resolving these through getLlmProvider at runtime
// in the page is done by a getLlmProvider() declared inside the page script.
export const GENERIC_ICON = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">' +
    '<rect width="32" height="32" rx="8" fill="#f8fafc"/>' +
    '<rect x="7" y="9" width="18" height="12" rx="2" fill="none" stroke="#64748b" stroke-width="2"/>' +
    '<path d="M12 25h8M16 21v4" stroke="#64748b" stroke-width="2" stroke-linecap="round"/>' +
    '</svg>';
// Provider id -> { label, icon }. ids are lowercase kebab-case to match the
// values returned by the v3 homepage API (profile.llm.payload.primaryProvider).
